"""LangGraph state definitions and structured LLM output schemas."""

from __future__ import annotations

import operator
from typing import Annotated, Any, Literal, TypedDict

from pydantic import BaseModel, Field

from app.schemas import AuditFinding, FinalAuditReport, RetrievedChunk, StrategyMetrics


class IntakePlan(BaseModel):
    """Structured triage plan generated by the Intake Supervisor agent."""

    intent: Literal["design_strategy", "audit_submitted_code", "high_risk_stress_test"]
    pine_search_query: str = Field(
        description="Targeted technical query for Pine Script v5 syntax & indicator functions"
    )
    risk_search_query: str = Field(
        description="Targeted query for anti-repainting traps, friction baseline & MiFID risk policies"
    )
    detected_leverage_x: float = Field(default=1.0, ge=1.0, le=125.0)
    requested_equity_pct: float = Field(default=15.0, ge=1.0, le=100.0)
    summary_note: str


class ArchitectDraft(BaseModel):
    """Structured quantitative strategy & audit draft generated by the Quant Architect agent."""

    strategy_title: str
    executive_summary: str
    pine_script_v5_code: str
    metrics: StrategyMetrics
    findings: list[AuditFinding]
    cited_doc_ids: list[str]


class TraceStep(TypedDict):
    """Telemetry record for a single executed node in the StateGraph."""

    node: str
    model_used: str
    latency_ms: int
    detail: str
    loop_iteration: int
    cost_usd_est: float


class RetrievalTaskState(TypedDict):
    """Sub-state dispatched via LangGraph Send() for parallel Qdrant hybrid retrieval."""

    track: Literal["pine_docs", "risk_policies"]
    query: str
    tenant: str


class AgentGraphState(TypedDict, total=False):
    """Root persistent state managed by LangGraph StateGraph + Checkpointer."""

    prompt: str
    tenant: str
    reasoning_tier: Literal["balanced", "deep"]

    # Triage & routing
    intake_plan: dict[str, Any]
    model_routing: dict[str, str]

    # Parallel fan-out reducer: merges chunks from concurrent Send() branches
    retrieved_chunks: Annotated[list[RetrievedChunk], operator.add]

    # Pre-audit static scan of user-submitted prompt/code
    input_trap_findings: list[AuditFinding]

    # Architect & Critic loop state
    draft: dict[str, Any]
    critic_issues: list[str]
    critic_passed: bool
    correction_loops: int

    # Governance & HITL interrupt state
    requires_human_approval: bool
    human_approval_reason: str
    triggered_policy_ids: list[str]
    human_decision: dict[str, str] | None

    # Final output & execution trace
    final_report: FinalAuditReport | None
    trace_steps: Annotated[list[TraceStep], operator.add]
